input.sparql:
SELECT ?entity ?name ?ts_uri ?ts_id WHERE {
  ?entity a ref:Point ;
          rdfs:label ?name .
  FILTER(?name IN ("AHU01", "CondPump02", "HWPump01"))
  ?entity ref:hasExternalReference ?ts_uri .
  ?ts_uri ref:hasTimeseriesId ?ts_id .
}

SELECT ?entity ?name WHERE {
  ?entity rdfs:label ?name .
  FILTER(CONTAINS(str(?name), "AHU") || CONTAINS(str(?name), "CondPump") || CONTAINS(str(?name), "HWPump"))
}

